"""Actual isolated selector and opaque account owner controls, not physical SQL."""
from pathlib import Path
import json,subprocess,unittest
ROOT=Path(__file__).resolve().parents[2]
class SessionFocused(unittest.TestCase):
 def test_actual_phase_selection_rejects_aliases_mixed_and_duplicate_modes(self):
  s=(ROOT/'support/governance/native-organization/test-native-organization-mysql.php').read_text();block=s[s.index('$arguments='):s.index('$workbench_http=')]
  for args,want in [(['--session-producer-lease'],'session-producer-lease'),(['--session-producer-lease=1'],'invalid'),(['--session-producer-lease','--session-producer-lease'],'invalid'),(['--session-producer-lease','--file-source-facts'],'invalid')]:
   code='$argv=array_merge(["driver"],json_decode($argv[2],true));'+block+'echo json_encode($phase);';p=subprocess.run(['php','-r',code,str(ROOT),json.dumps(args)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(json.loads(p.stdout),want)
  selected=s.split("}elseif($phase==='session-producer-lease'){",1)[1].split('}elseif(',1)[0];self.assertLess(selected.index('governance_completion_start_gorge'),selected.index('governance_recovery_session_lease_focused'));self.assertIn('session-lease-observer-or-physical-cleanup-unproved',s)
 def owner(self,mode):
  p=subprocess.run(['php',str(ROOT/'support/governance/recovery/tests/session-observer-owner-host.php'),str(ROOT),mode],capture_output=True,text=True,timeout=12);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');d=json.loads(p.stdout);self.assertFalse(d['physical_SQL_executed']);return d
 def test_actual_opaque_owner_creates_only_two_observer_grants_and_closes_owned_account(self):
  d=self.owner('good');self.assertIsNone(d['error']);self.assertIsNone(d['cleanup_error']);self.assertEqual((d['created'],d['grant_count'],d['dropped']),(1,2,1));self.assertFalse(d['account_retained']);self.assertTrue(d['cleanup']['native_writer_grants_unchanged']);self.assertGreater(d['thread_reads'],0)
 def test_preexisting_or_foreign_owner_never_dropped_and_CREATE_ACK_retains_cleanup_owner(self):
  d=self.owner('preexisting');self.assertEqual(d['error'],'session_observer_account_preexists');self.assertEqual((d['created'],d['dropped']),(0,0))
  d=self.owner('wrong-owner');self.assertEqual(d['error'],'session_observer_account_owner_unknown');self.assertIsNotNone(d['cleanup_error']);self.assertEqual(d['dropped'],0);self.assertTrue(d['account_retained'])
  d=self.owner('create-ACK');self.assertEqual(d['error'],'host_create_ACK_lost');self.assertEqual(d['dropped'],1);self.assertTrue(d['cleanup']['cleanup_proved'])
 def test_live_observer_SQL_session_prevents_drop(self):
  d=self.owner('live');self.assertIsNone(d['error']);self.assertEqual(d['cleanup_error'],'session_observer_owned_SQL_sessions_remaining');self.assertEqual(d['dropped'],0);self.assertTrue(d['account_retained'])
 def test_actual_native_initial_admission_guard_refuses_old_approved_insert_plan(self):
  code=r'''$root=$argv[1];function phutil_register_library_map($map){foreach($map['class']as$class=>$path){$GLOBALS['paths'][$class]=$GLOBALS['mapBase'].'/'.$path;}}foreach(['/support/runtime/src','/src']as$suffix){$GLOBALS['mapBase']=$root.$suffix;require$root.$suffix.'/__phutil_library_map__.php';}spl_autoload_register(function($class){if(isset($GLOBALS['paths'][$class]))require_once$GLOBALS['paths'][$class];});require_once$root.'/support/runtime/src/utils/utils.php';$text=file_get_contents($root.'/src/infrastructure/governance/recovery/PhorgeGovernanceRecoveryGuard.php');$start=strpos($text,'        if($user->getID()!==null ||');$end=strpos($text,'        PhorgeGovernanceRecoveryTransition::describe',$start);$condition=substr($text,$start,$end-$start);$out=[];foreach([0,1]as$approved){$user=(new PhabricatorUser())->setIsApproved($approved);try{eval($condition);$out[]='accepted-initial-condition';}catch(RuntimeException$e){$out[]=$e->getMessage();}}echo json_encode(['actual_native_class'=>get_class($user),'out'=>$out,'SQL_executed'=>false]);'''
  p=subprocess.run(['php','-r',code,str(ROOT)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');self.assertEqual(json.loads(p.stdout),{'actual_native_class':'PhabricatorUser','out':['accepted-initial-condition','recovery_initial_admission_unknown'],'SQL_executed':False})
  focused=(ROOT/'support/governance/recovery/session-lease-focused.php').read_text();self.assertLess(focused.index('governance_task_owner_prepare($fixture)'),focused.index("overrideEnvConfig('governance.account-recovery.enabled',true)"));self.assertIn("'subjects'=>array('commit'=>$users['subject'],'rollback'=>$users['other'])",focused)
  cases=(ROOT/'support/governance/recovery/session-lease-cases.php').read_text();self.assertNotIn("->setIsApproved(1)->save()",cases);self.assertIn('session_lease_prepared_subject_required',cases)
 def test_real_driver_refuses_missing_paired_File_before_observer_or_native_preparation(self):
  code=r'''putenv('PHORGE_GOVERNANCE_GORGE_FILE_BINARY');putenv('PHORGE_GOVERNANCE_GORGE_FILE_SHA256');class PhorgeGovernanceCompletionFixture{function assertOwned(){$GLOBALS['owned']++;}}function governance_recovery_session_lease_focused(...$args){$GLOBALS['prepared']=true;throw new Exception('unexpected_prepare');}$s=file_get_contents($argv[1].'/support/governance/native-organization/test-native-organization-mysql.php');$start=strpos($s,"}elseif($"."phase==='session-producer-lease'){")+strlen("}elseif($"."phase==='session-producer-lease'){");$end=strpos($s,'}elseif(',$start);$body=substr($s,$start,$end-$start);$body=str_replace('__DIR__',var_export($argv[1].'/support/governance/native-organization',true),$body);$owned=0;$prepared=false;$fixture=new PhorgeGovernanceCompletionFixture();$check=function(){throw new Exception('unexpected_ready');};$reason=null;try{eval($body);}catch(RuntimeException$e){$reason=$e->getMessage();}echo json_encode(['reason'=>$reason,'owned'=>$owned,'prepared'=>$prepared,'physical_SQL_executed'=>false]);'''
  p=subprocess.run(['php','-r',code,str(ROOT)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');self.assertEqual(json.loads(p.stdout),{'reason':'completion_paired_gorge_binary_required','owned':1,'prepared':False,'physical_SQL_executed':False})
 def test_actual_driver_cleanup_consumer_retains_unknown_fixture(self):
  code=r'''$s=file_get_contents($argv[1].'/support/governance/native-organization/test-native-organization-mysql.php');$start=strpos($s,'  if($borrowed_unknown){');$borrowed_unknown=false;$end=strpos($s,'  if(!$borrowed_unknown){if ($control !== null)',$start);$block=substr($s,$start,$end-$start);class Fixture{function cleanup(){$GLOBALS['drops']++;return['synthetic'=>true];}}$out=[];foreach([false,true]as$proof){$native_rr=false;$workbench_http=false;$notice_history=false;$task_browser=false;$phase='session-producer-lease';$GLOBALS['governance_session_lease_cleanup']=['cleanup_proved'=>$proof];$fixture=new Fixture();$cleanup_failures=[];$checks=[];$cleanup=null;$drops=0;eval($block);$out[]=['drops'=>$drops,'failure'=>$cleanup_failures,'checks'=>$checks];}echo json_encode($out);'''
  p=subprocess.run(['php','-r',code,str(ROOT)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');d=json.loads(p.stdout);self.assertEqual(d[0],{'drops':0,'failure':[{'stage':'session-lease-observer-or-physical-cleanup-unproved','error_type':'RuntimeException'}],'checks':[]});self.assertEqual(d[1]['drops'],1);self.assertEqual(d[1]['failure'],[])
 def test_actual_failure_projection_is_fixed_safe_and_failure_only(self):
  code=r'''require$argv[1].'/support/governance/recovery/session-lease-diagnostic.php';$secret='fixture-secret-SQL-password-account';$f=['stage'=>'focused-native-session-producer-lease','error_type'=>'RuntimeException','source_file'=>'session-lease-cases.php','source_line'=>12,'message'=>$secret,'SQL'=>$secret,'password'=>$secret];$child=['error_type'=>'other-'.$secret,'source_file'=>$secret.'.php','source_line'=>true,'query_code'=>1142,'raw'=>$secret];$out=[governance_recovery_session_lease_failure_projection('session-producer-lease',false,$f,$child),governance_recovery_session_lease_failure_projection('session-producer-lease',true,$f,$child),governance_recovery_session_lease_failure_projection('all',false,$f,$child)];echo json_encode($out);'''
  p=subprocess.run(['php','-r',code,str(ROOT)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');self.assertNotIn('fixture-secret',p.stdout);d=json.loads(p.stdout);self.assertEqual(d[1:],[None,None]);self.assertEqual(d[0]['failure'],{'error_type':'RuntimeException','source_file':'session-lease-cases.php','source_line':12,'query_code':None});self.assertEqual(d[0]['child_failure'],{'error_type':'other','source_file':None,'source_line':None,'query_code':1142})

 def test_actual_lease_unknown_begin_and_abort_keep_focused_driver_cleanup_closed(self):
  for case in ('unknown-begin','unknown-next','unknown-abort','abort-throws'):
   p=subprocess.run(['php',str(ROOT/'support/governance/recovery/tests/session-cleanup-gate-host.php'),str(ROOT),case],capture_output=True,text=True,timeout=10)
   self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');d=json.loads(p.stdout)
   self.assertFalse(d['physical_SQL_executed']);self.assertEqual(d['opens'],1);self.assertFalse(d['physical_cleanup_flag']);self.assertEqual(d['focused_error'],'session_lease_physical_cleanup_unproved');self.assertEqual(d['driver_drops'],0);self.assertEqual(d['driver_cleanup_failures'],[{'stage':'session-lease-observer-or-physical-cleanup-unproved','error_type':'RuntimeException'}])
 def test_actual_lease_known_terminal_and_abort_unlock_only_proved_cleanup(self):
  for case,state in [('commit','committed'),('rollback','rolled-back'),('abort','invalid')]:
   p=subprocess.run(['php',str(ROOT/'support/governance/recovery/tests/session-cleanup-gate-host.php'),str(ROOT),case],capture_output=True,text=True,timeout=10)
   self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');d=json.loads(p.stdout)
   self.assertFalse(d['physical_SQL_executed']);self.assertIsNone(d['error']);self.assertTrue(d['physical_cleanup_flag']);self.assertTrue(d['terminal']['cleanup_proved']);self.assertEqual(d['terminal']['state'],state);self.assertIsNone(d['focused_error']);self.assertEqual(d['driver_drops'],1);self.assertEqual(d['driver_cleanup_failures'],[])

 def test_fresh_process_loads_actual_native_factory_before_any_SQL(self):
  # Separate PHP processes: no previous normal fixture can mask the missing include.
  negative="require$argv[1].'/support/governance/native-organization/workers.php';echo json_encode(function_exists('governance_native_request'));"
  p=subprocess.run(['php','-r',negative,str(ROOT)],capture_output=True,text=True,timeout=10)
  self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');self.assertFalse(json.loads(p.stdout))
  positive=r"""require_once$argv[1].'/support/governance/recovery/session-lease-cases.php';require_once$argv[1].'/support/governance/recovery/session-lease-cases.php';$r=new ReflectionFunction('governance_native_request');echo json_encode(['file'=>realpath($r->getFileName()),'parameters'=>array_map(static fn($p)=>(string)$p->getType(),$r->getParameters()),'line'=>$r->getStartLine(),'SQL_executed'=>false]);"""
  p=subprocess.run(['php','-r',positive,str(ROOT)],capture_output=True,text=True,timeout=10)
  self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');self.assertEqual(json.loads(p.stdout),{'file':str((ROOT/'support/governance/native-organization/native-cases.php').resolve()),'parameters':['PhabricatorUser','PhabricatorAuthSessionEngine'],'line':4,'SQL_executed':False})

 def routing(self,mode):
  p=subprocess.run(['php',str(ROOT/'support/governance/recovery/tests/session-routing-native-host.php'),str(ROOT),mode],capture_output=True,text=True,timeout=10)
  self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');d=json.loads(p.stdout);self.assertFalse(d['SQL_executed']);self.assertTrue(d['restored']);self.assertEqual(d['owned_assertions'],1);return d
 def test_actual_native_Env_ScopedEnv_and_routing_reproduce_exact_third_dictionary_refusal(self):
  d=self.routing('old-third');self.assertEqual(d['error'],'recovery_config_scope_unknown');self.assertEqual(d['site'],{'file':'PhorgeRecoveryNativeCaptureScope.php','line':49});self.assertEqual(d['classes'],['PhabricatorConfigDictionarySource']*2+['PhabricatorConfigDefaultSource']);self.assertFalse(d['route_equal'])
 def test_actual_focused_flags_flatten_before_factory_and_restore_after_primary_failure(self):
  for mode in ('good','primary'):
   d=self.routing(mode);self.assertEqual(d['before_flatten_count'],3);self.assertEqual(d['classes'],['PhabricatorConfigDictionarySource','PhabricatorConfigDefaultSource']);self.assertTrue(d['lease_enabled']);self.assertTrue(d['route_equal']);self.assertEqual(d['primary_preserved'],mode=='primary');self.assertEqual(d['error'],'explicit-host-primary'if mode=='primary'else None)
  cases=(ROOT/'support/governance/recovery/session-lease-cases.php').read_text();self.assertNotIn('beginScopedEnv',cases)
  focused=(ROOT/'support/governance/recovery/session-lease-focused.php').read_text();self.assertLess(focused.index("overrideEnvConfig('governance.account-recovery.session-lease.enabled',true)"),focused.index('governance_recovery_account_fixture_environment($fixture)'))
 def test_actual_worker_settings_build_one_dictionary_without_inheriting_parent_scope(self):
  d=self.routing('worker');self.assertEqual(d['worker'],{'classes':['PhabricatorConfigDictionarySource','PhabricatorConfigDefaultSource'],'route_equal':True,'recovery_enabled':True,'incarnation_equal':True})
 def test_routing_diagnostic_only_exposes_fixed_class_basenames_without_raw_error(self):
  names=['PhorgeRecoveryNativeCaptureScope.php','PhorgeRecoveryRestoreProfile.php','PhorgeGovernanceNativeRuntimeProfile.php','account-cases.php','foreign.php']
  code="require$argv[1].'/support/governance/recovery/session-lease-diagnostic.php';$out=[];foreach(json_decode($argv[2],true)as$name){$out[]=governance_recovery_session_lease_failure_projection('session-producer-lease',false,['source_file'=>$name,'source_line'=>49,'message'=>'raw-secret-SQL','error_type'=>'RuntimeException']);}echo json_encode($out);"
  p=subprocess.run(['php','-r',code,str(ROOT),json.dumps(names)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');self.assertNotIn('raw-secret',p.stdout);d=json.loads(p.stdout);self.assertEqual([x['failure']['source_file']for x in d],names[:-1]+[None])
